/** Вымышленный номер (Twilio отклоняет) — единственный разрешённый получатель в тесте. */
export const FAKE_PHONE = { e164: '+15555550100', digits: '5555550100' } as const;

export const estimateUrl = (token: string | null) => (token === null ? '/estimate' : `/estimate?t=${token}`);

/** Гостевая публичная страница сметы: открыта, без экрана входа. */
export async function openPublicEstimate(page: Page, token: string | null) {
  await page.goto(estimateUrl(token));
  await expect(page).toHaveURL(/\/estimate(\?|$)/);
  await expect(page.getByText('Sign in to continue')).toHaveCount(0);
}

export type SmsCall = { url: string; body: string };

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
};

/**
 * Перехват отправки SMS: каждый POST к URL с «sms» запоминается и получает фейковый 200 (успех).
 * Запрос наружу не уходит. Возвращает список перехваченных вызовов.
 */
export async function fakeSmsSent(page: Page): Promise<SmsCall[]> {
  const calls: SmsCall[] = [];
  await page.route(/sms/i, async (route) => {
    const req: Request = route.request();
    if (req.resourceType() === 'document' || req.resourceType() === 'script' || req.resourceType() === 'stylesheet') {
      await route.fallback();
      return;
    }
    if (req.method() === 'OPTIONS') {
      await route.fulfill({ status: 204, headers: CORS, body: '' });
      return;
    }
    if (req.method() !== 'POST') {
      await route.fallback();
      return;
    }
    calls.push({ url: req.url(), body: req.postData() ?? '' });
    await route.fulfill({
      status: 200,
      headers: { ...CORS, 'content-type': 'application/json' },
      body: JSON.stringify({ success: true, ok: true, sid: 'SM-QA-AUTO', status: 'queued' }),
    });
  });
  return calls;
}

/** Все строковые значения JSON-тела (рекурсивно); если тело не JSON — само тело. */
export function bodyStrings(body: string): string[] {
  const out: string[] = [];
  const walk = (v: unknown) => {
    if (typeof v === 'string') out.push(v);
    else if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') Object.values(v as Record<string, unknown>).forEach(walk);
  };
  try { walk(JSON.parse(body)); } catch { out.push(body); }
  return out;
}

/** Текст SMS сметы — строковое поле тела, начинающееся с «Techory:» и содержащее «estimate». */
export function estimateSmsText(call: SmsCall): string {
  const text = bodyStrings(call.body).find((s) => /^Techory:/.test(s) && /estimate/i.test(s));
  expect(text, `в теле запроса SMS нет текста сметы — тело: ${call.body.slice(0, 500)}`).toBeTruthy();
  return text as string;
}

/** Каждый перехваченный SMS адресован только вымышленному номеру. */
export function expectOnlyFakePhone(calls: SmsCall[]) {
  for (const c of calls) {
    expect(c.body.replace(/\D/g, ''), `SMS только на ${FAKE_PHONE.e164}, тело: ${c.body.slice(0, 300)}`).toContain(FAKE_PHONE.digits);
  }
}

/** Разбор текста SMS сметы (формат ручной проверки 12.11). */
export function parseEstimateSms(text: string) {
  const m = text.match(/^Techory: Hi (.+?), your estimate #(\S*) from (.+?) for (\$[\d,]+(?:\.\d{2})?) is ready\. View it here: (\S+)/);
  return m ? { greeting: m[1], number: m[2], company: m[3], amount: m[4], link: m[5] } : null;
}

/** Create new → New Estimate → Select Client → клиент. */
export async function openNewEstimateForClient(page: Page, client: string) {
  await page.goto('/dashboard');
  await page.getByRole('button', { name: 'Create new' }).filter({ visible: true }).first().click();
  await page.getByText('New Estimate', { exact: true }).filter({ visible: true }).first().click();
  await page.waitForURL(/\/EstimateCreation/);
  const dialog = page.getByRole('dialog', { name: 'Select Client' });
  await expect(dialog).toBeVisible();
  const search = dialog.getByRole('textbox').first();
  if (await search.count()) await search.fill(client);
  await dialog.getByText(client, { exact: true }).first().click();
  await expect(dialog).toBeHidden();
}

/** Заголовок сметы и одна позиция (имя, количество 1, цена). Смету НЕ сохраняет. */
export async function fillEstimate(page: Page, title: string, item: { name: string; price: string }) {
  expect(title.startsWith('QA-AUTO'), 'данные теста — с префиксом QA-AUTO').toBe(true);
  await page.getByLabel(/^Title/).or(page.getByPlaceholder(/title/i)).first().fill(title);

  await page.getByRole('button', { name: /Add Item/i }).first().click();
  const itemDialog = page.getByRole('dialog').filter({ has: page.getByRole('button', { name: /^(Save|Add)/ }) }).last();
  const scope: Locator | Page = (await itemDialog.count()) ? itemDialog : page;
  await scope.getByLabel(/^(Item )?Name/i).or(scope.getByPlaceholder(/name/i)).first().fill(item.name);
  await scope.getByLabel(/Price|Unit Price|Rate/i).first().fill(item.price);
  await scope.getByRole('button', { name: /^(Save|Add)/ }).last().click();
  await expect(page.getByText(item.name).first()).toBeVisible();
}

/** Send → Send Estimate → Send via SMS → вымышленный номер → Send. */
export async function sendEstimateViaSms(page: Page) {
  await page.getByRole('button', { name: 'Send', exact: true }).filter({ visible: true }).last().click();
  const dialog = page.getByRole('dialog', { name: 'Send Estimate' });
  await expect(dialog).toBeVisible();
  await dialog.getByText('Send via SMS', { exact: true }).click();
  const phone = dialog.getByLabel('Phone Number').or(dialog.getByRole('textbox')).first();
  await phone.fill(FAKE_PHONE.e164);
  await expect(phone).toHaveValue(FAKE_PHONE.e164);
  await dialog.getByRole('button', { name: 'Send', exact: true }).click();
  await expect(dialog).toBeHidden({ timeout: 20_000 });
}

/** Строки списка Estimates (/assessments), отфильтрованные поиском по заголовку. */
export async function estimateRows(page: Page, title: string): Promise<Locator> {
  await page.goto('/assessments');
  await page.getByPlaceholder('Search estimates...').fill(title);
  return page.getByRole('row').filter({ hasText: title });
}

/** Очистка (по возможности, падение не роняет тест): Actions → Delete (или Archive) у сметы с этим заголовком. */
export async function removeEstimate(page: Page, title: string) {
  if (page.isClosed()) return;
  try {
    const rows = await estimateRows(page, title);
    const n = await rows.count();
    for (let i = 0; i < n; i++) {
      const row = rows.first();
      await row.getByRole('button', { name: /Actions/ }).click();
      const del = page.getByRole('menuitem', { name: /Delete/i });
      if (await del.count()) {
        await del.first().click();
        const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Delete|Confirm|Yes)/i });
        if (await confirm.count()) await confirm.first().click();
      } else {
        await page.getByRole('menuitem', { name: /Archive/i }).first().click();
      }
      await expect(rows).toHaveCount(n - i - 1, { timeout: 10_000 });
    }
  } catch (e) {
    console.warn(`очистка сметы «${title}» не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}
